export async function GET() {
  try {
    // 1. Perintah otomatis membuat tabel di MySQL
    await pool.query(`
      CREATE TABLE IF NOT EXISTS populasi_tw4_2025 (
        id INT AUTO_INCREMENT PRIMARY KEY,
        kecamatan VARCHAR(100),
        no_desa INT,
        desa VARCHAR(100),
        data_v JSON
      )
    `);

    // 2. Kosongkan tabel (mencegah data dobel kalau Mas tidak sengaja refresh webnya)
    await pool.query('TRUNCATE TABLE populasi_tw4_2025');

    // 3. Masukkan data dengan kecepatan tinggi
    for (const row of DATA_LENGKAP) {
      const vString = JSON.stringify(row.v);
      await pool.query(
        'INSERT INTO populasi_tw4_2025 (kecamatan, no_desa, desa, data_v) VALUES (?, ?, ?, ?)',
        [row.kec, row.no, row.desa, vString]
      );
    }

    return NextResponse.json({
      status: 'Sukses Berkibar! 🚀',
      pesan: `${DATA_LENGKAP.length} data desa se-Kabupaten berhasil mendarat di MySQL!`
    });
  } catch (error) {
    console.error(error);
    return NextResponse.json({ status: 'Gagal', error: 'Cek terminal VS Code' }, { status: 500 });
  }
}